#!/usr/bin/env python3
import sys, csv, json, re, collections

def is_num(x):
    try:
        float(x)
        return True
    except:
        return False

def get_val(r, key):
    v = r.get(key, "")
    if is_num(v):
        return float(v)
    return v

def parse_args():
    args = sys.argv[1:]
    opts = {'icsv': False, 'itsv': False, 'ijson': False, 'idkvp': True,
            'ocsv': False, 'otsv': False, 'ojson': False, 'odkvp': True,
            'headerless_csv_output': False}

    verbs = []
    files = []
    i = 0
    current_verb = None

    while i < len(args):
        arg = args[i]
        if arg == '--csv':
            opts.update({'icsv': True, 'ocsv': True, 'idkvp': False, 'odkvp': False})
        elif arg == '--tsv':
            opts.update({'itsv': True, 'otsv': True, 'idkvp': False, 'odkvp': False})
        elif arg == '--json':
            opts.update({'ijson': True, 'ojson': True, 'idkvp': False, 'odkvp': False})
        elif arg == '--idkvp':
            opts.update({'idkvp': True, 'icsv': False, 'itsv': False, 'ijson': False})
        elif arg == '--ocsv':
            opts.update({'ocsv': True, 'odkvp': False, 'otsv': False, 'ojson': False})
        elif arg == '--headerless-csv-output':
            opts['headerless_csv_output'] = True
        elif arg == 'then':
            current_verb = None
        elif arg.startswith('--'):
            pass # ignore other global flags for now
        elif not arg.startswith('-') and current_verb is None:
            current_verb = {'name': arg, 'args': []}
            verbs.append(current_verb)
        elif current_verb is not None and arg.startswith('-'):
            current_verb['args'].append(arg)
            # check if it takes a value
            if i+1 < len(args) and not args[i+1].startswith('-') and args[i+1] != 'then':
                current_verb['args'].append(args[i+1])
                i += 1
        elif current_verb is not None:
            if current_verb['name'] in ['put', 'filter'] and len(current_verb['args']) == 0:
                current_verb['args'].append(arg)
            else:
                files.append(arg)
        else:
            files.append(arg)
        i += 1
    return opts, verbs, files

def read_data(files, opts):
    records = []
    inputs = files if files else [sys.stdin]
    for f in inputs:
        fd = open(f, 'r') if isinstance(f, str) else f
        if opts['icsv'] or opts['itsv']:
            delim = '\t' if opts['itsv'] else ','
            reader = csv.DictReader(fd, delimiter=delim)
            for row in reader:
                records.append(dict(row))
        elif opts['ijson']:
            content = fd.read().strip()
            if not content: continue
            if content.startswith('['):
                data = json.loads(content)
                records.extend(data)
            else:
                for line in content.split('\n'):
                    if line.strip():
                        records.append(json.loads(line))
        else:
            # dkvp
            for line in fd:
                line = line.strip()
                if not line: continue
                r = {}
                for pair in line.split(','):
                    if '=' in pair:
                        k, v = pair.split('=', 1)
                        r[k] = v
                records.append(r)
        if isinstance(f, str): fd.close()
    return records

def apply_verb(records, verb):
    name = verb['name']
    args = verb['args']

    if name == 'cat':
        return records
    elif name == 'tac':
        return list(reversed(records))
    elif name == 'cut':
        fields = []
        exclude = False
        i = 0
        while i < len(args):
            if args[i] == '-f':
                fields = args[i+1].split(',')
                i += 1
            elif args[i] == '-x':
                exclude = True
            i += 1
        out = []
        for r in records:
            if exclude:
                out.append({k:v for k,v in r.items() if k not in fields})
            else:
                out.append({k:v for k,v in r.items() if k in fields})
        return out
    elif name == 'sort':
        # args like -f a,b -nr x
        # sort fields in reverse order to maintain stability
        sort_instructions = [] # tuples of (field, type, reverse)
        i = 0
        while i < len(args):
            flag = args[i]
            if flag in ['-f', '-n', '-nr', '-r']:
                fields = args[i+1].split(',')
                for f in fields:
                    sort_instructions.append((f, flag))
                i += 1
            i += 1

        for f, flag in reversed(sort_instructions):
            def key_func(r, f=f, flag=flag):
                v = r.get(f, "")
                if flag in ['-n', '-nr']:
                    try: return float(v)
                    except: return float('-inf') if flag == '-nr' else float('inf')
                return v
            reverse = (flag in ['-r', '-nr'])
            records.sort(key=key_func, reverse=reverse)
        return records
    elif name == 'stats1':
        aggs = []
        fields = []
        groups = []
        i = 0
        while i < len(args):
            if args[i] == '-a':
                aggs = args[i+1].split(',')
                i += 1
            elif args[i] == '-f':
                fields = args[i+1].split(',')
                i += 1
            elif args[i] == '-g':
                groups = args[i+1].split(',')
                i += 1
            i += 1

        grouped = collections.defaultdict(list)
        for r in records:
            gk = tuple(r.get(g, "") for g in groups)
            grouped[gk].append(r)

        out = []
        for gk, recs in grouped.items():
            res = {}
            for g_name, g_val in zip(groups, gk):
                res[g_name] = g_val
            for f in fields:
                vals = []
                for r in recs:
                    v = r.get(f, "")
                    if is_num(v): vals.append(float(v))

                for a in aggs:
                    key = f"{f}_{a}"
                    if a == 'count':
                        res[key] = len(recs)
                    elif not vals:
                        res[key] = ""
                    elif a == 'min':
                        res[key] = min(vals)
                    elif a == 'max':
                        res[key] = max(vals)
                    elif a == 'sum':
                        res[key] = sum(vals)
                    elif a == 'mean':
                        res[key] = sum(vals)/len(vals) if len(vals)>0 else ""
            out.append(res)
        return out
    elif name == 'filter':
        expr = args[0]
        # extremely basic mapping for evaluation
        # $foo -> get_val(r, "foo")
        py_expr = re.sub(r'\$([a-zA-Z0-9_]+)', r'get_val(r, "\1")', expr)
        py_expr = py_expr.replace('||', ' or ').replace('&&', ' and ')
        out = []
        for r in records:
            try:
                if eval(py_expr, {'get_val': get_val, 'r': r}):
                    out.append(r)
            except:
                pass
        return out
    elif name == 'put':
        expr = args[0]
        out = []
        for r in records:
            r_copy = dict(r)
            # handle assignments $z = $x + $y
            # this is very hacky
            try:
                if '=' in expr:
                    lhs, rhs = expr.split('=', 1)
                    lhs = lhs.strip().replace('$', '')
                    py_rhs = re.sub(r'\$([a-zA-Z0-9_]+)', r'get_val(r, "\1")', rhs)
                    r_copy[lhs] = eval(py_rhs, {'get_val': get_val, 'r': r})
            except:
                pass
            out.append(r_copy)
        return out
    return records

def write_data(records, opts):
    if not records:
        return
    if opts['ocsv'] or opts['otsv']:
        delim = '\t' if opts['otsv'] else ','
        fields = []
        for r in records:
            for k in r.keys():
                if k not in fields:
                    fields.append(k)
        writer = csv.DictWriter(sys.stdout, fieldnames=fields, delimiter=delim)
        if not opts['headerless_csv_output']:
            writer.writeheader()
        writer.writerows(records)
    elif opts['ojson']:
        print(json.dumps(records, indent=2))
    else:
        for r in records:
            line = ",".join(f"{k}={v}" for k, v in r.items())
            print(line)

def main():
    opts, verbs, files = parse_args()
    records = read_data(files, opts)
    for v in verbs:
        records = apply_verb(records, v)
    write_data(records, opts)

if __name__ == '__main__':
    main()
