                    v = r.get(f, "")
                    try: vals.append(float(v))
                    except: pass
                for a in aggs:
                    key = f"{f}_{a}"
                    if not vals and a != 'count': continue
                    if a == 'count': res[key] = len(recs)
                    elif a == 'min': res[key] = format_num(min(vals))
                    elif a == 'max': res[key] = format_num(max(vals))
                    elif a == 'sum': res[key] = format_num(sum(vals))
                    elif a == 'mean': res[key] = format_num(sum(vals)/len(vals))
            out.append(res)
        return out
    return records

def write_data(records, opts):
    if not records: return
    if opts['ocsv'] or opts['otsv']:
        delim = '\t' if opts['otsv'] else ','
        fields = []
        for r in records:
            for k in r.keys():
                if k not in fields: fields.append(k)
        writer = csv.DictWriter(sys.stdout, fieldnames=fields, delimiter=delim)
        if not opts['headerless']: writer.writeheader()
        writer.writerows(records)
    elif opts['ojson']: print(json.dumps(records, indent=2))
    elif opts['opprint']:
        fields = []
        for r in records:
            for k in r.keys():
                if k not in fields: fields.append(k)
        widths = {f: len(f) for f in fields}
        for r in records:
            for f in fields: widths[f] = max(widths[f], len(str(r.get(f, ""))))
        header = " ".join(f.ljust(widths[f]) for f in fields)
        print(header)
        for r in records:
            line = " ".join(str(r.get(f, "")).ljust(widths[f]) for f in fields)
            print(line)
    else:
        for r in records: print(",".join(f"{k}={v}" for k, v in r.items()))

def main():
    opts, verbs, files = parse_args(sys.argv[1:])
    records = read_data(files, opts)
    for v in verbs: records = apply_verb(records, v)
    write_data(records, opts)

if __name__ == '__main__':
    main()
